class Solution:
    def reverseKSubarrays(self, nums: List[int], k: int) -> List[int]:
        sz = len(nums) // k
        for i in range(0, len(nums), sz):
            l, r = i, i + sz - 1
            while l < r:
                nums[l], nums[r] = nums[r], nums[l]
                l += 1; r -= 1
        return nums

