class Solution {
public:
    vector<int> reverseKSubarrays(vector<int>& nums, int k) {
        int sz = nums.size() / k;
        for (int i = 0; i < (int)nums.size(); i += sz)
            reverse(nums.begin() + i, nums.begin() + i + sz);
        return nums;
    }
};

