class Solution {
    public int[] reverseKSubarrays(int[] nums, int k) {
        int sz = nums.length / k;
        for (int i = 0; i < nums.length; i += sz)
            for (int l = i, r = i + sz - 1; l < r; l++, r--) {
                int t = nums[l]; nums[l] = nums[r]; nums[r] = t;
            }
        return nums;
    }
}

