var reverseKSubarrays = function(nums, k) {
    const sz = nums.length / k;
    for (let i = 0; i < nums.length; i += sz) {
        let l = i, r = i + sz - 1;
        while (l < r) { [nums[l], nums[r]] = [nums[r], nums[l]]; l++; r--; }
    }
    return nums;
};
